28	function findOrCreateLobby(game) {
29	  for (const lobby of lobbies.values()) {
30	    if (lobby.gameId === game.id && lobby.members.size < game.config.maxPlayers) return lobby;
31	  }
32	  const lobby = {
33	    id: game.id + ':' + uid(6),
34	    gameId: game.id,
35	    members: new Map(), // userId -> {ws, user, pos, stage, score, lastTouch}
36	    mode: game.config.mode,
37	    modeState: { itId: null, lastTag: 0, coinsTaken: {} }, // coinsTaken: partId -> respawnAt
38	    created: Date.now(),
39	  };
