55	function leaderboard(lobby) {
56	  const entries = [...lobby.members.values()].map((m) => ({
57	    id: m.user.id,
58	    username: m.user.username,
59	    stage: m.stage,
60	    score: m.score,
61	    it: lobby.mode === 'tag' && lobby.modeState.itId === m.user.id,
62	  }));
63	  if (lobby.mode === 'obby') entries.sort((a, b) => b.stage - a.stage);
64	  else entries.sort((a, b) => b.score - a.score);
65	  return entries;
