68	function pickIt(lobby) {
69	  const ids = [...lobby.members.keys()];
70	  if (ids.length < 2) { lobby.modeState.itId = null; return; }
71	  lobby.modeState.itId = ids[Math.floor(Math.random() * ids.length)];
72	  lobby.modeState.lastTag = Date.now();
