154	function partCenterAt(part, timeMs) {
155	  // movers oscillate on a triangle wave keyed to server epoch time
156	  if (part.type !== 'mover') return [part.x, part.y, part.z];
157	  const t = (timeMs / 1000) / part.period % 2;
158	  const tri = t < 1 ? t : 2 - t;
159	  return [part.x + part.dx * tri, part.y + part.dy * tri, part.z + part.dz * tri];
160	}
