162	function handlePlayMsg(ws, member, lobby, msg) {
163	  const db = get();
164	  const game = db.games[lobby.gameId];
165	  if (!game) return;
166	
167	  switch (msg.t) {
168	    case 'move': {
169	      if (Array.isArray(msg.p) && msg.p.length === 3 && msg.p.every(Number.isFinite)) {
170	        member.pos = msg.p;
171	        member.yaw = Number(msg.yaw) || 0;
172	        member.anim = typeof msg.anim === 'string' ? msg.anim.slice(0, 12) : 'idle';
173	        broadcast(lobby, { t: 'p', id: member.user.id, p: member.pos, yaw: member.yaw, anim: member.anim }, member.user.id);
174	      }
175	      break;
176	    }
177	    case 'chat': {
178	      const text = String(msg.text || '').slice(0, 200).trim();
179	      if (!text) break;
180	      broadcast(lobby, { t: 'chat', id: member.user.id, username: member.user.username, text });
181	      send(ws, { t: 'chat', id: member.user.id, username: member.user.username, text });
182	      break;
183	    }
184	    case 'touch': {
185	      // server-validated interactions: coins and goals
186	      const part = game.world.parts.find((p) => p.id === msg.partId);
187	      if (!part) break;
188	      const c = partCenterAt(part, Date.now());
189	      const reach = Math.max(part.sx, part.sy, part.sz) / 2 + 4;
190	      if (dist2(member.pos, c) > reach * reach) break; // too far — reject
191	      if (part.type === 'coin') {
192	        const taken = lobby.modeState.coinsTaken[part.id];
193	        if (taken && taken > Date.now()) break;
194	        lobby.modeState.coinsTaken[part.id] = Date.now() + 10000;
195	        member.score++;
196	        broadcast(lobby, { t: 'coin', partId: part.id, by: member.user.id, respawnAt: lobby.modeState.coinsTaken[part.id] });
197	        send(ws, { t: 'coin', partId: part.id, by: member.user.id, respawnAt: lobby.modeState.coinsTaken[part.id] });
198	        broadcast(lobby, { t: 'lb', entries: leaderboard(lobby), itId: lobby.modeState.itId });
199	      } else if (part.type === 'goal') {
200	        if (member.finished) break;
201	        member.finished = true;
202	        member.score += 10;
203	        // first-completion glimmer prize for obby mode
204	        if (!member.user.system) { member.user.glimmers += 5; save(); }
205	        broadcast(lobby, { t: 'goalhit', by: member.user.id, username: member.user.username });
206	        send(ws, { t: 'goalhit', by: member.user.id, username: member.user.username, reward: 5 });
207	        broadcast(lobby, { t: 'lb', entries: leaderboard(lobby), itId: lobby.modeState.itId });
208	      }
209	      break;
210	    }
211	    case 'stage': {
212	      const n = Math.round(Number(msg.n) || 0);
213	      if (n > member.stage && n < 1000) {
214	        member.stage = n;
215	        broadcast(lobby, { t: 'lb', entries: leaderboard(lobby), itId: lobby.modeState.itId });
216	        send(ws, { t: 'lb', entries: leaderboard(lobby), itId: lobby.modeState.itId });
217	      }
218	      break;
219	    }
220	    case 'died': {
221	      broadcast(lobby, { t: 'pdied', id: member.user.id }, member.user.id);
222	      break;
223	    }
224	  }
225	}
