227	// tag proximity check loop — server decides who is "it"
228	setInterval(() => {
229	  for (const lobby of lobbies.values()) {
230	    if (lobby.mode !== 'tag' || !lobby.modeState.itId) continue;
231	    if (Date.now() - lobby.modeState.lastTag < 2000) continue; // tagback cooldown
