235	      if (m.user.id === it.user.id) continue;
236	      if (dist2(it.pos, m.pos) < 2.2 * 2.2) {
237	        lobby.modeState.itId = m.user.id;
238	        lobby.modeState.lastTag = Date.now();
239	        it.score++; // points for passing the zap
240	        broadcast(lobby, { t: 'tag', itId: m.user.id, by: it.user.id });
241	        broadcast(lobby, { t: 'lb', entries: leaderboard(lobby), itId: lobby.modeState.itId });
242	        break;
243	      }
