281	function handleStudioMsg(ws, member, st, msg) {
282	  const db = get();
283	  const game = db.games[st.gameId];
284	  if (!game) return;
285	
286	  switch (msg.t) {
287	    case 'op': {
288	      const op = msg.op || {};
289	      let applied = null;
290	      if (op.kind === 'add') {
291	        if (game.world.parts.length >= MAX_PARTS) {
292	          send(ws, { t: 'error', error: `Part limit (${MAX_PARTS}) reached` });
293	          return;
294	        }
295	        const part = sanitizePart(op.part);
296	        if (!part) return;
297	        // ensure unique id
298	        if (game.world.parts.some((p) => p.id === part.id)) part.id = uid(8);
299	        game.world.parts.push(part);
300	        applied = { kind: 'add', part };
301	      } else if (op.kind === 'update') {
302	        const part = sanitizePart(op.part);
303	        if (!part) return;
304	        const i = game.world.parts.findIndex((p) => p.id === part.id);
305	        if (i < 0) return;
306	        game.world.parts[i] = part;
307	        applied = { kind: 'update', part };
308	      } else if (op.kind === 'del') {
309	        const i = game.world.parts.findIndex((p) => p.id === op.partId);
310	        if (i < 0) return;
311	        game.world.parts.splice(i, 1);
312	        applied = { kind: 'del', partId: op.partId };
313	      } else if (op.kind === 'meta') {
314	        applyConfig(game, op.data || {});
315	        applied = {
316	          kind: 'meta',
317	          data: { name: game.name, desc: game.desc, genre: game.genre, public: game.public, config: game.config },
318	        };
319	      }
320	      if (applied) {
321	        game.updated = Date.now();
322	        save();
323	        broadcast(st, { t: 'op', from: member.user.id, op: applied }, member.user.id);
324	        send(ws, { t: 'opok', op: applied });
325	      }
326	      break;
327	    }
328	    case 'sel': {
329	      member.sel = typeof msg.partId === 'string' ? msg.partId : null;
330	      broadcast(st, { t: 'sel', id: member.user.id, partId: member.sel }, member.user.id);
331	      break;
332	    }
333	    case 'chat': {
334	      const text = String(msg.text || '').slice(0, 200).trim();
335	      if (!text) break;
336	      broadcast(st, { t: 'chat', id: member.user.id, username: member.user.username, text });
337	      send(ws, { t: 'chat', id: member.user.id, username: member.user.username, text });
338	      break;
339	    }
340	  }
341	}
