345	function attach(server, apiRouter) {
346	  const wss = new WebSocketServer({ server, path: '/ws' });
347	  wss.on('error', () => {}); // http server owns error handling (port retry)
348	  apiRouter.presence = () => presence;
349	
350	  wss.on('connection', (ws, req) => {
351	    const user = userFromReq(req);
352	    if (!user) {
353	      send(ws, { t: 'error', error: 'Not logged in' });
354	      ws.close();
355	      return;
356	    }
357	    ws.isAlive = true;
358	    ws.on('pong', () => { ws.isAlive = true; });
359	
360	    ws.on('message', (raw) => {
361	      let msg;
362	      try { msg = JSON.parse(raw); } catch (e) { return; }
363	      if (typeof msg !== 'object' || !msg) return;
364	
365	      const db = get();
366	      if (msg.t === 'join' || msg.t === 'studio') {
367	        leaveRoom(ws);
368	        const game = db.games[msg.gameId];
369	        if (!game) { send(ws, { t: 'error', error: 'Game not found' }); return; }
370	        if (msg.t === 'join') {
371	          if (!game.public && !(game.ownerId === user.id || game.collaborators.includes(user.id))) {
372	            send(ws, { t: 'error', error: 'This place is private' });
373	            return;
374	          }
375	          joinLobby(ws, db.users[user.id], game);
376	        } else {
377	          joinStudio(ws, db.users[user.id], game);
378	        }
379	        return;
380	      }
381	      const room = ws._room;
382	      if (!room) return;
383	      if (room.kind === 'play') {
384	        const member = room.lobby.members.get(user.id);
385	        if (member && member.ws === ws) handlePlayMsg(ws, member, room.lobby, msg);
386	      } else if (room.kind === 'studio') {
387	        const member = room.studio.members.get(user.id);
388	        if (member && member.ws === ws) handleStudioMsg(ws, member, room.studio, msg);
389	      }
390	    });
391	
392	    ws.on('close', () => leaveRoom(ws));
393	    ws.on('error', () => leaveRoom(ws));
394	  });
395	
396	  // heartbeat: drop dead sockets so lobbies don't fill with ghosts
397	  setInterval(() => {
398	    for (const ws of wss.clients) {
399	      if (!ws.isAlive) { try { ws.terminate(); } catch (e) {} continue; }
400	      ws.isAlive = false;
401	      try { ws.ping(); } catch (e) {}
402	    }
403	  }, 15000);
404	
405	  return wss;
406	}
407	
408	module.exports = { attach };
