// NEONSTRIKE — multiplayer server. Static files + WebSocket rooms.
// Zero config: `node server/index.js` and go.
const http = require('http');
const fs = require('fs');
const path = require('path');
const crypto = require('crypto');
const { WebSocketServer } = require('ws');

const PUBLIC_DIR = path.join(__dirname, '..', 'public');
const PORT = Number(process.env.PORT) || 3002;

const MAPS = ['vector', 'foundry', 'canopy'];
const MAX_PLAYERS = 8;
const KILL_TARGET = 15;
// unambiguous alphabet: no 0/O/1/I
const CODE_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZ23456789';

const MIME = {
  '.html': 'text/html; charset=utf-8',
  '.js': 'text/javascript; charset=utf-8',
  '.css': 'text/css; charset=utf-8',
  '.json': 'application/json; charset=utf-8',
  '.png': 'image/png',
};

// code -> room { code, map, players: Map<id, player>, resetTimer }
const rooms = new Map();

function uid(n) {
  return crypto.randomBytes(n).toString('base64url').slice(0, n);
}

function roomCode() {
  let code;
  do {
    code = '';
    for (let i = 0; i < 4; i++) {
      code += CODE_ALPHABET[crypto.randomInt(CODE_ALPHABET.length)];
    }
  } while (rooms.has(code));
  return code;
}

function send(ws, msg) {
  if (ws.readyState === 1) ws.send(JSON.stringify(msg));
}

function broadcast(room, msg, exceptId) {
  const raw = JSON.stringify(msg);
  for (const p of room.players.values()) {
    if (p.id !== exceptId && p.ws.readyState === 1) p.ws.send(raw);
  }
}

function scoreList(room) {
  return [...room.players.values()].map((p) => ({
    id: p.id,
    name: p.name,
    kills: p.kills,
    deaths: p.deaths,
  }));
}

function createRoom(ws, msg) {
  const name = String(msg.name || 'player').slice(0, 24);
  const map = MAPS.includes(msg.map) ? msg.map : MAPS[0];
  const room = { code: roomCode(), map, players: new Map(), resetTimer: null };
  rooms.set(room.code, room);
  const player = makePlayer(ws, name);
  room.players.set(player.id, player);
  ws._room = room;
  ws._playerId = player.id;
  send(ws, { t: 'created', code: room.code, id: player.id });
}

function makePlayer(ws, name) {
  return { id: uid(8), ws, name, hp: 100, kills: 0, deaths: 0, lastState: null };
}

function joinRoom(ws, msg) {
  const code = String(msg.code || '').toUpperCase();
  const room = rooms.get(code);
  if (!room) { send(ws, { t: 'error', msg: 'Room not found' }); return; }
  if (room.players.size >= MAX_PLAYERS) { send(ws, { t: 'error', msg: 'Room is full' }); return; }
  const name = String(msg.name || 'player').slice(0, 24);
  const player = makePlayer(ws, name);
  room.players.set(player.id, player);
  ws._room = room;
  ws._playerId = player.id;
  send(ws, {
    t: 'joined',
    id: player.id,
    code: room.code,
    map: room.map,
    players: scoreList(room).filter((p) => p.id !== player.id),
  });
  // snapshot of where everyone currently is
  for (const p of room.players.values()) {
    if (p.id !== player.id && p.lastState) send(ws, { t: 'state', id: p.id, ...p.lastState });
  }
  broadcast(room, { t: 'player_join', id: player.id, name: player.name }, player.id);
}

function leaveRoom(ws) {
  const room = ws._room;
  if (!room) return;
  const id = ws._playerId;
  ws._room = null;
  ws._playerId = null;
  if (!room.players.delete(id)) return;
  broadcast(room, { t: 'player_leave', id });
  if (room.players.size === 0) {
    if (room.resetTimer) clearTimeout(room.resetTimer);
    rooms.delete(room.code);
  }
}

function handleHit(room, shooter, msg) {
  const victim = room.players.get(String(msg.target || ''));
  if (!victim || victim.id === shooter.id || victim.hp <= 0) return;
  const dmg = Math.max(0, Math.min(200, Number(msg.dmg) || 0));
  const head = !!msg.head;
  victim.hp = Math.max(0, victim.hp - dmg);
  broadcast(room, { t: 'damage', id: victim.id, hp: victim.hp, from: shooter.id });
  if (victim.hp <= 0) {
    shooter.kills++;
    victim.deaths++;
    broadcast(room, { t: 'death', id: victim.id, by: shooter.id, head });
    broadcast(room, { t: 'scores', players: scoreList(room) });
    if (shooter.kills >= KILL_TARGET && !room.resetTimer) {
      broadcast(room, { t: 'match_over', winner: { id: shooter.id, name: shooter.name } });
      room.resetTimer = setTimeout(() => {
        room.resetTimer = null;
        for (const p of room.players.values()) { p.kills = 0; p.deaths = 0; }
        broadcast(room, { t: 'scores', players: scoreList(room) });
      }, 5000);
    }
  }
}

function handleMessage(ws, msg) {
  if (msg.t === 'create') { leaveRoom(ws); createRoom(ws, msg); return; }
  if (msg.t === 'join') { leaveRoom(ws); joinRoom(ws, msg); return; }

  const room = ws._room;
  if (!room) return;
  const player = room.players.get(ws._playerId);
  if (!player || player.ws !== ws) return;

  switch (msg.t) {
    case 'state': {
      const { t, ...rest } = msg;
      player.lastState = rest;
      broadcast(room, { t: 'state', id: player.id, ...rest }, player.id);
      break;
    }
    case 'shoot': {
      broadcast(room, { t: 'shoot', id: player.id, weapon: msg.weapon }, player.id);
      break;
    }
    case 'hit': {
      handleHit(room, player, msg);
      break;
    }
    case 'respawn': {
      if (player.hp > 0) break;
      player.hp = 100;
      broadcast(room, { t: 'respawned', id: player.id, hp: 100 });
      break;
    }
    case 'leave': {
      leaveRoom(ws);
      break;
    }
  }
}

// ---------------- http static server ----------------

const server = http.createServer((req, res) => {
  let urlPath;
  try {
    urlPath = decodeURIComponent(req.url.split('?')[0]);
  } catch (e) {
    res.writeHead(400); res.end('bad request'); return;
  }
  if (urlPath === '/') urlPath = '/index.html';
  const filePath = path.join(PUBLIC_DIR, urlPath);
  if (!filePath.startsWith(PUBLIC_DIR)) { res.writeHead(403); res.end('forbidden'); return; }
  const mime = MIME[path.extname(filePath).toLowerCase()];
  fs.readFile(filePath, (err, data) => {
    if (err || !mime) { res.writeHead(404); res.end('not found'); return; }
    res.writeHead(200, { 'Content-Type': mime });
    res.end(data);
  });
});

// ---------------- websocket wiring ----------------

const wss = new WebSocketServer({ server, path: '/ws' });

wss.on('connection', (ws) => {
  ws.isAlive = true;
  ws.on('pong', () => { ws.isAlive = true; });

  ws.on('message', (raw) => {
    try {
      const msg = JSON.parse(raw);
      if (!msg || typeof msg !== 'object' || typeof msg.t !== 'string') return;
      handleMessage(ws, msg);
    } catch (e) {
      // never crash on malformed input
    }
  });

  ws.on('close', () => leaveRoom(ws));
  ws.on('error', () => leaveRoom(ws));
});

// heartbeat: drop dead sockets so rooms don't fill with ghosts
setInterval(() => {
  for (const ws of wss.clients) {
    if (!ws.isAlive) { try { ws.terminate(); } catch (e) {} continue; }
    ws.isAlive = false;
    try { ws.ping(); } catch (e) {}
  }
}, 20000);

server.listen(PORT, () => {
  console.log(`NEONSTRIKE server running at http://localhost:${PORT}`);
});

// NEONSTRIKE — multiplayer client. WebSocket protocol + remote player tracking.

const LERP_RATE = 12; // exponential ease rate toward latest server state

export class Net {
  constructor() {
    this.ws = null;
    this.id = null;
    this.code = null;
    this.handlers = new Map(); // type -> [fn]
    this.pending = new Map(); // type -> {resolve, reject}
    this.remotePlayers = new Map(); // id -> remote player record
  }

  connect() {
    return new Promise((resolve, reject) => {
      const proto = location.protocol === 'https:' ? 'wss' : 'ws';
      const ws = new WebSocket(proto + '://' + location.host + '/ws');
      const timer = setTimeout(() => {
        reject(new Error('connect timeout'));
        try { ws.close(); } catch (e) {}
      }, 5000);
      ws.onopen = () => {
        clearTimeout(timer);
        this.ws = ws;
        resolve();
      };
      ws.onerror = () => {
        clearTimeout(timer);
        reject(new Error('connection failed'));
      };
      ws.onmessage = (ev) => {
        let msg;
        try { msg = JSON.parse(ev.data); } catch (e) { return; }
        if (msg && typeof msg === 'object') this._route(msg);
      };
      ws.onclose = () => {
        this.ws = null;
        for (const [, p] of this.pending) p.reject(new Error('disconnected'));
        this.pending.clear();
        this._emit('disconnect', {});
      };
    });
  }

  on(type, fn) {
    if (!this.handlers.has(type)) this.handlers.set(type, []);
    this.handlers.get(type).push(fn);
  }

  _emit(type, msg) {
    const fns = this.handlers.get(type);
    if (fns) for (const fn of fns) fn(msg);
  }

  _send(msg) {
    if (this.ws && this.ws.readyState === 1) this.ws.send(JSON.stringify(msg));
  }

  _request(sendMsg, replyType) {
    return new Promise((resolve, reject) => {
      this.pending.set(replyType, { resolve, reject });
      this._send(sendMsg);
    });
  }

  createRoom(name, map) {
    return this._request({ t: 'create', name, map }, 'created').then((msg) => {
      this.id = msg.id;
      this.code = msg.code;
      return { code: msg.code, id: msg.id };
    });
  }

  joinRoom(code, name) {
    return this._request({ t: 'join', code, name }, 'joined').then((msg) => {
      this.id = msg.id;
      this.code = msg.code;
      for (const p of msg.players) this._addRemote(p.id, p.name, p.kills, p.deaths);
      return { id: msg.id, code: msg.code, map: msg.map, players: msg.players };
    });
  }

  sendState(obj) { this._send({ t: 'state', ...obj }); }
  sendShoot(weapon) { this._send({ t: 'shoot', weapon }); }
  sendHit(targetId, dmg, head) { this._send({ t: 'hit', target: targetId, dmg, head }); }
  sendRespawn() { this._send({ t: 'respawn' }); }
  leave() {
    this._send({ t: 'leave' });
    this.id = null;
    this.code = null;
    this.remotePlayers.clear();
  }

  _addRemote(id, name, kills, deaths) {
    if (this.remotePlayers.has(id)) return this.remotePlayers.get(id);
    const rp = {
      name: name || '?',
      x: 0, y: 0, z: 0, yaw: 0, pitch: 0,
      crouch: false, weapon: null, hp: 100,
      kills: kills || 0, deaths: deaths || 0,
      lastT: performance.now(),
      cur: { x: 0, y: 0, z: 0, yaw: 0 },
      hasState: false,
    };
    this.remotePlayers.set(id, rp);
    return rp;
  }

  _route(msg) {
    // resolve pending create/join requests
    if (msg.t === 'created' || msg.t === 'joined') {
      const p = this.pending.get(msg.t);
      if (p) { this.pending.delete(msg.t); p.resolve(msg); }
      return;
    }
    if (msg.t === 'error') {
      for (const [type, p] of this.pending) {
        this.pending.delete(type);
        p.reject(new Error(msg.msg));
        return;
      }
      return;
    }

    // maintain remotePlayers from room traffic
    switch (msg.t) {
      case 'player_join': {
        this._addRemote(msg.id, msg.name);
        break;
      }
      case 'player_leave': {
        this.remotePlayers.delete(msg.id);
        break;
      }
      case 'state': {
        const rp = this._addRemote(msg.id);
        rp.x = msg.x; rp.y = msg.y; rp.z = msg.z;
        rp.yaw = msg.yaw; rp.pitch = msg.pitch;
        rp.crouch = !!msg.crouch;
        rp.weapon = msg.weapon;
        if (typeof msg.hp === 'number') rp.hp = msg.hp;
        rp.lastT = performance.now();
        if (!rp.hasState) {
          rp.cur = { x: msg.x, y: msg.y, z: msg.z, yaw: msg.yaw };
          rp.hasState = true;
        }
        break;
      }
      case 'damage': {
        const rp = this.remotePlayers.get(msg.id);
        if (rp) rp.hp = msg.hp;
        break;
      }
      case 'respawned': {
        const rp = this.remotePlayers.get(msg.id);
        if (rp) rp.hp = msg.hp;
        break;
      }
      case 'death': {
        const rp = this.remotePlayers.get(msg.id);
        if (rp) rp.hp = 0;
        break;
      }
      case 'scores': {
        for (const p of msg.players) {
          if (p.id === this.id) continue;
          const rp = this._addRemote(p.id, p.name);
          rp.name = p.name;
          rp.kills = p.kills;
          rp.deaths = p.deaths;
        }
        break;
      }
    }

    this._emit(msg.t, msg);
  }

  // ease each remote player's rendered position toward the latest received state
  lerpStates(dt) {
    const k = 1 - Math.exp(-LERP_RATE * dt);
    for (const rp of this.remotePlayers.values()) {
      const c = rp.cur;
      c.x += (rp.x - c.x) * k;
      c.y += (rp.y - c.y) * k;
      c.z += (rp.z - c.z) * k;
      // shortest-arc yaw blend so players don't spin the long way round
      let dyaw = rp.yaw - c.yaw;
      while (dyaw > Math.PI) dyaw -= Math.PI * 2;
      while (dyaw < -Math.PI) dyaw += Math.PI * 2;
      c.yaw += dyaw * k;
    }
  }

  getRenderList() {
    const out = [];
    for (const [id, rp] of this.remotePlayers) {
      out.push({
        id,
        name: rp.name,
        x: rp.cur.x, y: rp.cur.y, z: rp.cur.z,
        yaw: rp.cur.yaw,
        crouch: rp.crouch,
        hp: rp.hp,
        weapon: rp.weapon,
      });
    }
    return out;
  }
}

